BEGIN TRANSACTION;
CREATE TABLE "artigo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "autor" varchar(150) NOT NULL, "ano" integer NOT NULL, "resumo" text NULL, "url_capa" varchar(300) NULL, "url_leitura" varchar(300) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "especialista" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" varchar(150) NOT NULL, "especialidade" varchar(100) NOT NULL, "crm" varchar(30) NULL, "telefone_whatsapp" varchar(20) NOT NULL, "url_foto" varchar(300) NULL);
CREATE TABLE "passo_rotina_feito" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "data" date NOT NULL, "periodo" varchar(10) NOT NULL, "titulo" varchar(50) NOT NULL, "produto_id" integer unsigned NOT NULL CHECK ("produto_id" >= 0), "marcado_em" datetime NOT NULL, "id_usuario" integer NOT NULL REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "perfil_dermatologico" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "idade" integer NOT NULL, "tipo_pele" varchar(10) NOT NULL, "alergias" text NULL, "objetivo" varchar(200) NOT NULL, "preferencia_produto" varchar(10) NOT NULL, "usa_maquiagem_diariamente" varchar(10) NOT NULL, "foto_rosto" varchar(500) NULL, "dados_ia" text NULL, "porcentagem_saude" integer NOT NULL, "fototipo" integer NULL, "id_usuario" integer NOT NULL UNIQUE REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY DEFERRED, "exercicio_frequencia" varchar(10) NOT NULL, "protetor_solar" integer NOT NULL, "sono_horas" varchar(10) NOT NULL, "gestante" bool NOT NULL, "sensibilidade" bool NOT NULL, "tipo_acne" varchar(20) NOT NULL);
CREATE TABLE "produto" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "marca" varchar(100) NOT NULL, "nome" varchar(200) NOT NULL, "categoria" varchar(30) NOT NULL, "tipo_pele" varchar(100) NOT NULL, "preocupacao" varchar(255) NOT NULL, "modo_uso" varchar(20) NOT NULL, "ingrediente_principal" varchar(100) NOT NULL, "fps" smallint unsigned NULL CHECK ("fps" >= 0), "tamanho_ml" integer unsigned NOT NULL CHECK ("tamanho_ml" >= 0), "preco" decimal NULL, "avaliacao" decimal NULL, "num_avaliacoes" integer unsigned NULL CHECK ("num_avaliacoes" >= 0), "descricao" text NOT NULL, "imagem_url" varchar(300) NOT NULL, "link_produto" varchar(300) NOT NULL, "slug" varchar(250) NOT NULL UNIQUE, "fonte" varchar(100) NOT NULL);
CREATE TABLE "regra_tratamento" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "faixa_etaria" varchar(10) NOT NULL, "tipo_pele" varchar(10) NOT NULL, "subtipo_pele" varchar(50) NOT NULL, "sensibilidade" bool NOT NULL, "preocupacao" varchar(50) NOT NULL, "tipo_interno" varchar(30) NOT NULL, "ingredientes" varchar(200) NOT NULL, "efeitos" text NOT NULL);
CREATE TABLE "usuario" ("id_usuario" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome_usuario" varchar(100) NOT NULL, "email" varchar(200) NOT NULL UNIQUE, "senha_usuario" varchar(100) NOT NULL, "data_cadastro" datetime NOT NULL);
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE UNIQUE INDEX "regra_tratamento_faixa_etaria_tipo_pele_subtipo_pele_sensibilidade_preocupacao_tipo_interno_853b61c3_uniq" ON "regra_tratamento" ("faixa_etaria", "tipo_pele", "subtipo_pele", "sensibilidade", "preocupacao", "tipo_interno");
CREATE UNIQUE INDEX "passo_rotina_feito_id_usuario_data_periodo_titulo_produto_id_759f3a7a_uniq" ON "passo_rotina_feito" ("id_usuario", "data", "periodo", "titulo", "produto_id");
CREATE INDEX "passo_rotina_feito_id_usuario_7081d435" ON "passo_rotina_feito" ("id_usuario");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
DELETE FROM "sqlite_sequence";
COMMIT;